How can I write a C++ program to identify three European countries where the second and third letters of their names are the same? Here's a starting code:
#include <iostream>
#include <string>
#include <fstream>
using namespace std;
int main()
{
    ifstream file("european_countries.txt"); // file containing European countries
    string country;
    while (getline(file, country))
    {
        // check if second and third letters are the same
        if (country.length() >= 3 && country[1] == country[2])
        {
            // output country name
            cout << country << endl;
        }
    }
    return 0;
} 
Assuming a file named "european_countries.txt" exists in the same directory as the program, this code will read each line of the file and output any European countries where the second and third letters of their names are the same.

