```
// Define the laptop struct
struct Laptop {
    var name: String
    var processor: String
    var ram: Int
    var storage: Int
    var displayResolution: String
    var batteryLife: Int
    var portability: String
    var durability: String
    var price: Double
}
// Define a function to filter laptops based on various specifications and price range
func filterLaptops(laptops: [Laptop], processor: String?, ram: Int?, storage: Int?, displayResolution: String?, batteryLife: Int?, portability: String?, durability: String?, priceRange: ClosedRange<Double>) -> [Laptop] {
    return laptops.filter { laptop in
        // Filter by processor
        if let processor = processor, laptop.processor != processor {
            return false
        }

        // Filter by RAM
        if let ram = ram, laptop.ram != ram {
            return false
        }

        // Filter by storage
        if let storage = storage, laptop.storage != storage {
            return false
        }

        // Filter by display resolution
        if let displayResolution = displayResolution, laptop.displayResolution != displayResolution {
            return false
        }

        // Filter by battery life
        if let batteryLife = batteryLife, laptop.batteryLife < batteryLife {
            return false
        }

        // Filter by portability
        if let portability = portability, laptop.portability != portability {
            return false
        }

        // Filter by durability
        if let durability = durability, laptop.durability != durability {
            return false
        }

        // Filter by price range
        if laptop.price > priceRange.upperBound || laptop.price < priceRange.lowerBound {
            return false
        }

        // If all filters pass, return true
        return true
    }
}
