```
#include <iostream>
using namespace std;
int main() {
    int n, t1 = 0, t2 = 1, nextTerm = 0;
    cout << "Enter the number of terms: ";
    cin >> n;
    // Check if user input is valid
    while (n <= 0) {
        cout << "Invalid input. Please enter a positive integer: ";
        cin >> n;
    }
    // Generate Fibonacci sequence
    int fib[n];
    fib[0] = t1;
    fib[1] = t2;
    for (int i = 2; i < n; ++i) {
        nextTerm = t1 + t2;
        t1 = t2;
